insert into public.school_exam_questions (question_id, exam_id, section_id, question_number, question_type, question_text, correct_answer, statement_json, topic, obsidian_source_path, has_image, metadata, difficulty_level) values ('supplemental-gtln-gtnn-reviewed-q13', 'supplemental-gtln-gtnn-reviewed', 'supplemental-gtln-gtnn-reviewed-multiple_choice', 13, 'multiple_choice', 'Một đường dây điện được mắc từ điểm $A$ trên đất liền đến đảo tại điểm $C$. Biết $AB=4\,km$, $BC=1\,km$, chi phí đi trên đất liền là $3000\,$USD/km và đi ngầm dưới biển là $5000\,$USD/km. Nếu chọn điểm $S$ nằm giữa $A$ và $B$ để nối $A\to S\to C$, thì $S$ phải cách $A$ bao nhiêu km để tổng chi phí nhỏ nhất?', 'C', '[]'::jsonb, 'Cực trị, GTLN và GTNN', 'Toan_Hoc/1_Ham_So/3_gia_tri_lon_nhat_nho_nhat.md', false, '{"source_question_number":13,"section_number":1,"source":"supplemental_local"}'::jsonb, 4);
