insert into public.school_exam_questions (question_id, exam_id, section_id, question_number, question_type, question_text, correct_answer, statement_json, topic, obsidian_source_path, has_image, metadata, difficulty_level) values ('supplemental-gtln-gtnn-reviewed-q14', 'supplemental-gtln-gtnn-reviewed', 'supplemental-gtln-gtnn-reviewed-multiple_choice', 14, 'multiple_choice', 'Một sợi dây kim loại dài $60\,cm$ được cắt thành hai đoạn. Đoạn thứ nhất uốn thành hình vuông cạnh $a$, đoạn thứ hai uốn thành đường tròn bán kính $r$. Để tổng diện tích hai hình nhỏ nhất thì tỉ số $\dfrac{a}{r}$ bằng', 'B', '[]'::jsonb, 'Cực trị, GTLN và GTNN', 'Toan_Hoc/1_Ham_So/3_gia_tri_lon_nhat_nho_nhat.md', false, '{"source_question_number":14,"section_number":1,"source":"supplemental_local"}'::jsonb, 4);
